    for (UEdGraphNode* Node : Graph->Nodes)
    {
        UAnimStateNode* StateNode = Cast<UAnimStateNode>(Node);
        if (StateNode && StateNode->GetStateName().Equals(StateName.ToString(), ESearchCase::IgnoreCase))
        {
            return StateNode;
