    Root->SetStringField(TEXT("asset_name"), AnimBlueprint->GetName());
    Root->SetStringField(TEXT("asset_path"), AnimBlueprint->GetPathName());
    Root->SetBoolField(TEXT("save_attempted"), Package != nullptr);
