def _load(unreal, asset_path):
    asset = unreal.EditorAssetLibrary.load_asset(asset_path)
    if not asset:
        raise ValueError(f"Niagara asset not found: {asset_path}")
    return asset

def _split_package_asset_path(asset_path):
    normalized = str(asset_path or "").strip().replace("\\", "/")
    if not normalized.startswith("/"):
        normalized = "/Game/" + normalized.lstrip("/")
    normalized = normalized.rsplit(".", 1)[0]
    package_path, _, asset_name = normalized.rpartition("/")
    if not package_path or not asset_name:
        raise ValueError(f"Expected Unreal package path like /Game/FX/NE_Name, got: {asset_path}")
    return package_path, asset_name, package_path + "/" + asset_name

def _readback_asset(unreal, asset_path):
    asset = unreal.EditorAssetLibrary.load_asset(asset_path)
    if not asset:
        return {"exists": False, "asset_path": asset_path}
    row = {
        "exists": True,
        "asset_path": asset_path,
        "name": asset.get_name(),
        "class": asset.get_class().get_name(),
        "properties": [],
    }
    for prop in ("exposed_parameters", "fixed_bounds", "warmup_time", "warmup_tick_count"):
        try:
            value = asset.get_editor_property(prop)
            row["properties"].append({"name": prop, "value": str(value)})
        except Exception:
            pass
    return row

def _set_requested_properties(asset, parameters):
    applied = []
    rejected = []
    for name, value in (parameters or {}).items():
        try:
            asset.set_editor_property(str(name), value)
            applied.append(str(name))
        except Exception as exc:
            rejected.append({"name": str(name), "error": str(exc)})
    return applied, rejected

def inspect_system(asset_path):
    import unreal

    asset = _load(unreal, asset_path)
    rows = {
        "asset_path": asset_path,
        "name": asset.get_name(),
        "class": asset.get_class().get_name(),
        "properties": [],
    }
    for name in ("exposed_parameters", "fixed_bounds", "warmup_time", "warmup_tick_count"):
        try:
            rows["properties"].append({"name": name, "value": asset.get_editor_property(name)})
        except Exception:
            pass
    return _result(ok=True, **rows)

def create_emitter(asset_path, template="empty", parameters=None):
    import unreal

    package_path, asset_name, normalized_path = _split_package_asset_path(asset_path)
    parameters = parameters or {}
    if isinstance(parameters, str):
        parameters = json.loads(parameters or "{}")
    if not isinstance(parameters, dict):
        raise TypeError("parameters must be a dict or JSON object string")

    existing = unreal.EditorAssetLibrary.load_asset(normalized_path)
    if existing:
        return _result(
            ok=False,
            status="asset_already_exists",
            asset_path=normalized_path,
            readback=_readback_asset(unreal, normalized_path),
        )

    template_asset = None
    if isinstance(template, str) and template.startswith(("/Game/", "/Engine/", "/Plugin/")):
        template_asset = unreal.EditorAssetLibrary.load_asset(template)
        if not template_asset:
            return _result(ok=False, status="template_not_found", asset_path=normalized_path, template=template)
        asset = unreal.EditorAssetLibrary.duplicate_asset(template, normalized_path)
        creation_strategy = "duplicate_template_asset"
    else:
        factory_cls = getattr(unreal, "NiagaraEmitterFactoryNew", None)
        emitter_cls = getattr(unreal, "NiagaraEmitter", None)
        if not factory_cls or not emitter_cls:
            return _result(
                ok=False,
                status="api_unavailable",
                asset_path=normalized_path,
                missing=[
                    name
                    for name, value in (
                        ("NiagaraEmitterFactoryNew", factory_cls),
                        ("NiagaraEmitter", emitter_cls),
                    )
                    if not value
                ],
            )
        asset_tools = unreal.AssetToolsHelpers.get_asset_tools()
        factory = factory_cls()
        for prop, value in (
            ("create_new", True),
            ("edit_after_new", False),
        ):
            try:
                factory.set_editor_property(prop, value)
            except Exception:
                pass
        asset = asset_tools.create_asset(asset_name, package_path, emitter_cls, factory)
        creation_strategy = "niagara_emitter_factory_new"

    if not asset:
        return _result(ok=False, status="create_asset_failed", asset_path=normalized_path, template=template)

    applied, rejected = _set_requested_properties(asset, parameters)
    saved = bool(unreal.EditorAssetLibrary.save_loaded_asset(asset, False))
    readback = _readback_asset(unreal, normalized_path)
    return _result(
        ok=bool(saved and readback.get("exists")),
        status="created" if saved and readback.get("exists") else "created_but_save_or_readback_failed",
        asset_path=normalized_path,
        template=template,
        template_asset=template_asset.get_path_name() if template_asset else "",
        strategy=creation_strategy,
        parameters_applied=applied,
        parameters_rejected=rejected,
        saved=saved,
        readback=readback,
    )

def add_to_level(asset_path, location=None, attach_to_selected_actor=False):
    import unreal

    system = _load(unreal, asset_path)
    location = location or [0.0, 0.0, 0.0]
    cls = getattr(unreal, "NiagaraActor", None)
    if not cls:
        return _result(ok=False, status="api_unavailable", api="NiagaraActor", asset_path=asset_path)
    actor = unreal.EditorLevelLibrary.spawn_actor_from_class(cls, unreal.Vector(float(location[0]), float(location[1]), float(location[2])))
    if not actor:
        return _result(ok=False, error="spawn_failed", asset_path=asset_path)
    try:
        comp = actor.get_component_by_class(unreal.NiagaraComponent)
        if comp:
            comp.set_asset(system)
    except Exception:
        pass
    return _result(ok=True, asset_path=asset_path, actor_path=actor.get_path_name(), location=location, attach_to_selected_actor=bool(attach_to_selected_actor))

def is_unreal_niagara_create_request(text: str) -> bool:
    q = (text or "").lower()
    if "unreal" not in q:
        return False
    if not any(verb in q for verb in UNREAL_PROTOTYPE_VERBS):
        return False
    return any(
        term in q for term in ("niagara", "niagra", "emitter", "particle system", "vfx")
    )

def _requested_fx_source_strategy(text: str) -> str:
    q = (text or "").lower()
    if any(term in q for term in ("outline", "silhouette", "rim", "edge")) and any(
        term in q for term in ("camera", "view", "screen", "facing")
    ):
        return "camera_facing_character_outline"
    if any(term in q for term in ("mesh emitter", "mesh source", "mesh surface", "surface emitter", "surface source")):
        return "skeletal_mesh_surface"
    if any(term in q for term in ("custom emitter source", "custom source", "custom niagara source")):
        return "custom_emitter_source"
    if any(term in q for term in ("socket", "bone", "joint", "hand", "foot", "head", "spine")):
        return "socket_or_bone"
    if any(term in q for term in ("around character", "on the character", "attached", "attach")):
        return "attached_component"
    return ""

def is_unreal_editable_character_fx_request(text: str) -> bool:
    q = (text or "").lower()
    if "unreal" not in q:
        return False
    if not any(term in q for term in ("niagara", "niagra", "vfx", "particle", "fx")):
        return False
    if not any(term in q for term in ("character", "player", "pawn", "bp_", "blueprint", "lester", "manny")):
        return False
    source_strategy = _requested_fx_source_strategy(text)
    return bool(source_strategy) and any(
        term in q for term in ("editable", "tunable", "param", "parameter", "variables", "expose", "designer")
    )

def build_unreal_niagara_create_params(
    text: str,
    target_root: str = "/Game/AIStudio/Prototypes/Niagara",
) -> dict[str, Any]:
    q = (text or "").lower()
    wants_emitter = any(
        term in q for term in ("emitter", "niagara emitter", "niagra emitter")
    )
    requested_name = extract_unreal_asset_name(text)
    base_name = requested_name or ("NE_AIStudioEmitter" if wants_emitter else "NS_AIStudioSystem")
    parameters: dict[str, Any] = {
        "request_text": text,
        "return_created_name": True,
        "asset_kind": "emitter" if wants_emitter else "system",
    }
    color = extract_requested_color(text)
    if color:
        parameters["requested_color"] = color
    target_blueprint = extract_target_blueprint_name(text, exclude_asset=base_name)
    if target_blueprint:
        parameters["target_blueprint"] = target_blueprint
        parameters["add_to_selected_blueprint"] = True
    attach_bone = extract_attachment_bone_name(text)
    if attach_bone:
        parameters["attach_bone"] = attach_bone
    return {
        "asset_path": f"{target_root.rstrip('/')}/{base_name}",
        "template": "empty_emitter" if wants_emitter else "empty_system",
        "asset_name": base_name,
        "parameters": parameters,
    }

def extract_attachment_bone_name(text: str) -> str:
    q = text or ""
    match = re.search(r"\b(?:to|onto|on|at)\s+(?:the\s+)?([A-Za-z][A-Za-z0-9_]*)(?:\s+(?:bone|joint|socket))\b", q, re.IGNORECASE)
    if match:
        return match.group(1).strip()
    match = re.search(r"\b([lr]_[A-Za-z0-9_]*(?:hand|foot|arm|leg)[A-Za-z0-9_]*)\b", q, re.IGNORECASE)
    if match:
        return match.group(1).strip()
    lower = q.lower()
    if "left hand" in lower:
        return "l_hand"
    if "right hand" in lower:
        return "r_hand"
    return ""

def operation_catalog() -> list[dict[str, Any]]:
    return [
        {
            "key": op.key,
            "label": op.label,
            "function": op.function,
            "required": list(op.required),
            "optional": op.optional,
            "mutates_project": op.mutates_project,
            "execution_host": op.execution_host,
            "description": op.description,
        }
        for op in UNREAL_OPERATIONS.values()
    ]

def unreal_operation_payload(
    operation_key: str, params: dict[str, Any] | None = None
) -> dict[str, Any]:
    if operation_key not in UNREAL_OPERATIONS:
        valid = ", ".join(sorted(UNREAL_OPERATIONS))
        raise ValueError(
            f"Unknown Unreal operation '{operation_key}'. Valid operations: {valid}"
        )

    op = UNREAL_OPERATIONS[operation_key]
    params = dict(params or {})
    missing = [
        name for name in op.required if name not in params or params[name] in (None, "")
    ]
    if missing:
        raise ValueError(
            f"Unreal operation '{operation_key}' requires: {', '.join(missing)}"
        )

    kwargs = dict(op.optional)
    kwargs.update(params)
    return {
        "operation": op.key,
        "label": op.label,
        "function": op.function,
        "args": [],
        "kwargs": kwargs,
        "mutates_project": op.mutates_project,
        "execution_host": op.execution_host,
    }

